<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('student');$sid=(int)current_user()['id'];$eid=get_int('id');$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id JOIN class_students cs ON cs.class_id=e.class_id AND cs.student_id=? WHERE e.id=? AND e.status='published'");$s->execute([$sid,$eid]);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد یا برای شما فعال نیست.');$nowTs=time();$startTs=!empty($exam['starts_at'])?strtotime($exam['starts_at']):null;$endTs=!empty($exam['ends_at'])?strtotime($exam['ends_at']):null;if($startTs&&$nowTs<$startTs)exit('این آزمون هنوز شروع نشده است. زمان شروع: '.e($exam['starts_at']));if($endTs&&$nowTs>$endTs)exit('مهلت شرکت در این آزمون به پایان رسیده است.');$s=db()->prepare('SELECT q.*,GROUP_CONCAT(CONCAT(o.id,"::",o.option_key,"::",o.option_text,"::",COALESCE(o.image_path,"")) ORDER BY o.sort_order SEPARATOR "||") option_data FROM questions q LEFT JOIN question_options o ON o.question_id=q.id WHERE q.exam_id=? GROUP BY q.id ORDER BY q.sort_order');$s->execute([$eid]);$questions=$s->fetchAll();$s=db()->prepare('SELECT * FROM attempts WHERE exam_id=? AND student_id=? AND revoked_at IS NULL ORDER BY attempt_no DESC,id DESC');$s->execute([$eid,$sid]);$attempts=$s->fetchAll();$maxAttempts=max(1,(int)($exam['max_attempts']??1));$attemptCount=count($attempts);if($attemptCount>=$maxAttempts){$chosen=$attempts[0];if(($exam['score_policy']??'latest')==='best'){foreach($attempts as $candidate){if((float)($candidate['score']??0)>(float)($chosen['score']??0))$chosen=$candidate;}}redirect('student/result.php?id='.$chosen['id']);}$attemptNo=$attemptCount+1;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo=db();$pdo->beginTransaction();try{$now=date('Y-m-d H:i:s');$x=$pdo->prepare('INSERT INTO attempts(exam_id,student_id,attempt_no,started_at,submitted_at,status,score,percentage) VALUES(?,?,?,?,? ,"submitted",?,?)');$x->execute([$eid,$sid,$attemptNo,$now,$now,0,0]);$aid=(int)$pdo->lastInsertId();$score=0;$max=0;foreach($questions as $q){$max+=(float)$q['score'];$key='q_'.$q['id'];$answer=post_string($key);$correct=null;$awarded=$q['question_type']==='short'?null:0;$selected=null;if(in_array($q['question_type'],['mcq','true_false'],true)){foreach(explode('||',(string)$q['option_data']) as $raw){[$oid,$ok,$ot,$oi]=array_pad(explode('::',$raw,4),4,'');if($ok===$answer){$selected=(int)$oid; $correct=(int)$pdo->query('SELECT is_correct FROM question_options WHERE id='.(int)$oid)->fetchColumn();$awarded=$correct?(float)$q['score']:0;break;}}}$score+=$awarded;$z=$pdo->prepare('INSERT INTO answers(attempt_id,question_id,answer_text,selected_option_id,is_correct,awarded_score) VALUES(?,?,?,?,?,?)');$z->execute([$aid,$q['id'],$q['question_type']==='short'?$answer:null,$selected,$correct,$awarded]);}$pct=$max>0?($score/$max*100):0;$z=$pdo->prepare('UPDATE attempts SET score=?,percentage=? WHERE id=?');$z->execute([$score,$pct,$aid]);$pdo->commit();audit('submit','attempt',$aid);flash('success','آزمون شما ثبت شد.');redirect('student/result.php?id='.$aid);}catch(Throwable $e){$pdo->rollBack();flash('error','ثبت پاسخ‌ها انجام نشد. لطفاً دوباره تلاش کنید.');}}
$title='پاسخ‌گویی آزمون';require __DIR__.'/../partials/header.php';?><h1><?=e($exam['title'])?></h1><div class="card"><div id="examTimer" class="alert info" data-duration="<?=e((string)((int)$exam['duration_minutes']*60))?>" data-exam="<?=e((string)$eid)?>">زمان باقی‌مانده: در حال محاسبه...</div><p><?=e($exam['instructions'])?></p><nav class="exam-toc" aria-label="پیمایش سؤال‌ها"><?php foreach($questions as $i=>$tocQuestion): ?><a href="#question-<?=$tocQuestion['id']?>"><?=($i+1)?></a><?php endforeach; ?></nav><p class="muted">درس: <?=e($exam['subject_title'])?> | مدت: <?=$exam['duration_minutes']?> دقیقه | نمره کل: <?=e($exam['total_score'])?> | تلاش <?=e((string)$attemptNo)?> از <?=e((string)$maxAttempts)?></p><form id="examForm" method="post" onsubmit="if(!confirm('پس از ثبت، امکان ویرایش پاسخ‌ها وجود ندارد. ادامه می‌دهید؟'))return false;localStorage.removeItem('exam_deadline_<?=$eid?>');localStorage.removeItem('exam_answers_<?=$eid?>');window.examSubmitted=true;this.querySelector('button[type=submit]').disabled=true;return true;"><?=csrf_field()?><?php foreach($questions as $i=>$q):?><div class="question" id="question-<?=$q['id']?>"><strong><?=($i+1).'. '.e($q['question_text'])?></strong><?php if(!empty($q['image_path'])):?><img class="question-image" src="<?=e(url($q['image_path']))?>" alt="تصویر سؤال"><?php endif;?><div class="muted">نمره: <?=e($q['score'])?></div><?php if(in_array($q['question_type'],['mcq','true_false'],true)):foreach(explode('||',(string)$q['option_data']) as $raw):[$oid,$ok,$ot,$oi]=array_pad(explode('::',$raw,4),4,'');if($ot==='')continue;?><label class="option"><input type="radio" name="q_<?=$q['id']?>" value="<?=e($ok)?>"> <?=e($ok)?>) <?=e($ot)?><?php if($oi!==''):?><img class="option-image" src="<?=e(url($oi))?>" alt="تصویر گزینه"><?php endif;?></label><?php endforeach;else:?><textarea name="q_<?=$q['id']?>" placeholder="پاسخ خود را بنویسید..."></textarea><?php endif;?></div><?php endforeach;?><button class="btn btn-success" type="submit">ثبت نهایی آزمون</button></form></div><script>(function(){var box=document.getElementById('examTimer'),form=document.getElementById('examForm');if(!box||!form)return;var key='exam_deadline_'+box.dataset.exam,deadline=Number(localStorage.getItem(key)||0),duration=Number(box.dataset.duration||0);if(!deadline||deadline<Date.now()){deadline=Date.now()+duration*1000;localStorage.setItem(key,String(deadline));}function tick(){var left=Math.max(0,Math.ceil((deadline-Date.now())/1000)),m=Math.floor(left/60),s=left%60;box.textContent='زمان باقی‌مانده: '+m+' دقیقه و '+String(s).padStart(2,'0')+' ثانیه';if(left<=60)box.className='alert warning';if(left<=0){box.textContent='زمان آزمون به پایان رسید؛ پاسخ‌ها در حال ثبت هستند.';localStorage.removeItem(key);var submitButton=form.querySelector('button[type=submit]');if(submitButton)submitButton.disabled=true;form.onsubmit=null;window.examSubmitted=true;form.submit();return;}setTimeout(tick,1000);}tick();})();</script><script>(function(){var form=document.getElementById('examForm'),key='exam_answers_<?=$eid?>';if(!form)return;var saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch(e){}Array.prototype.forEach.call(form.querySelectorAll('input[name^="q_"],textarea[name^="q_"]'),function(el){if(el.type==='radio'){if(saved[el.name]===el.value)el.checked=true;}else if(Object.prototype.hasOwnProperty.call(saved,el.name)){el.value=saved[el.name];}el.addEventListener('input',save);el.addEventListener('change',save);});function save(){var data={};Array.prototype.forEach.call(form.querySelectorAll('input[name^="q_"],textarea[name^="q_"]'),function(el){if(el.type==='radio'){if(el.checked)data[el.name]=el.value;}else if(el.value!=='')data[el.name]=el.value;});try{localStorage.setItem(key,JSON.stringify(data));}catch(e){}}window.addEventListener('beforeunload',function(event){if(window.examSubmitted)return;event.preventDefault();event.returnValue='پاسخ‌های شما هنوز ثبت نهایی نشده است.';});})();</script><?php require __DIR__.'/../partials/footer.php'; ?>
